public void initBalanceDetails()
{
    LeaveRequest        request = LeaveRequest_ds.cursor();
    LeaveRequestDetail  requestDetail;
    select firstonly requestDetail 
        where requestDetail.Request == request.RecId;

    LeaveTypeRecId currrentLeaveType = requestDetail.LeaveType;
    real totalDays = request.getTotalAmount();
    NVLeaveBalanceDetailsTmp detailsTmp = NVLeaveBalanceDetailsTmp::balanceByLeaveType(request.Worker, request.getStartDate() - 1, currrentLeaveType, request.getStartDate(), totalDays);

    NVLeaveBalanceDetailsTmp.setTmpData(detailsTmp);
    NVLeaveBalanceDetailsTmp_ds.executeQuery();
    NVLeaveBalanceDetailsTmp_ds.research(true);
}
